// safeDialer wraps the default dialer with SSRF protection
func safeDialer(addr string) (net.Conn, error) {
	// Extract host from addr (format is host:port)
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, errors.New("invalid address format")
	}

	// Resolve the hostname to IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, errors.New("failed to resolve hostname")
	}

	// Check all resolved IPs for safety
	for _, ip := range ips {
		if !isPublicIP(ip) {
			return nil, errors.New("access to internal networks is not allowed")
		}
	}

	// Safe to dial
	return fasthttp.DialDualStackTimeout(addr, 10*time.Second)
}

// isPublicIP checks if an IP address is a public (non-internal) address
func isPublicIP(ip net.IP) bool {
	if ip == nil {
		return false
	}

	// Check for loopback
	if ip.IsLoopback() {
		return false
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return false
	}

	// Check for link-local
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return false
	}

	// Check for private networks
	if ip.IsPrivate() {
		return false
	}

	// Check for multicast
	if ip.IsMulticast() {
		return false
	}

	// Additional checks for IPv4
	if ip4 := ip.To4(); ip4 != nil {
		// 169.254.0.0/16 - Link-local
		if ip4[0] == 169 && ip4[1] == 254 {
			return false
		}
		// 127.0.0.0/8 - Loopback
		if ip4[0] == 127 {
			return false
		}
		// 0.0.0.0/8 - Current network
		if ip4[0] == 0 {
			return false
		}
		// 100.64.0.0/10 - Shared address space (CGN)
		if ip4[0] == 100 && ip4[1] >= 64 && ip4[1] <= 127 {
			return false
		}
		// 192.0.0.0/24 - IETF Protocol Assignments
		if ip4[0] == 192 && ip4[1] == 0 && ip4[2] == 0 {
			return false
		}
		// 192.0.2.0/24 - TEST-NET-1
		if ip4[0] == 192 && ip4[1] == 0 && ip4[2] == 2 {
			return false
		}
		// 198.51.100.0/24 - TEST-NET-2
		if ip4[0] == 198 && ip4[1] == 51 && ip4[2] == 100 {
			return false
		}
		// 203.0.113.0/24 - TEST-NET-3
		if ip4[0] == 203 && ip4[1] == 0 && ip4[2] == 113 {
