		}
		// 240.0.0.0/4 - Reserved
		if ip4[0] >= 240 {
			return false
		}
	}

	return true
}

// validateURL performs initial URL validation before making requests
func validateURL(rawURL string) error {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return errors.New("invalid URL format")
	}

	// Only allow http and https schemes
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return errors.New("only http and https schemes are allowed")
	}

	// Check for empty host
	if parsedURL.Hostname() == "" {
		return errors.New("URL must have a valid hostname")
	}

	host := parsedURL.Hostname()

	// Block localhost variations
	lowerHost := strings.ToLower(host)
	if lowerHost == "localhost" || strings.HasSuffix(lowerHost, ".localhost") {
		return errors.New("access to localhost is not allowed")
	}

	// Block common internal hostnames
	blockedHosts := []string{
		"metadata.google.internal",
		"metadata.goog",
		"169.254.169.254",
		"metadata",
		"kubernetes.default",
	}
	for _, blocked := range blockedHosts {
		if lowerHost == blocked || strings.HasSuffix(lowerHost, "."+blocked) {
			return errors.New("access to internal services is not allowed")
		}
	}

	// If host is an IP address, validate it directly
	if ip := net.ParseIP(host); ip != nil {
		if !isPublicIP(ip) {
			return errors.New("access to internal networks is not allowed")
		}
	}

	return nil
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	// Parse request body
	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{Error: "Invalid JSON body"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{Error: "URL field is required"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	// Validate URL for SSRF protection
	if err := validateURL(req.URL); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{URL: req.URL, Error: err.Error()}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	// Fetch the URL content
	statusCode, body, err := fetchURL(req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		response := URLPreviewResponse{URL: req.URL, Error: err.Error()}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		response := URLPreviewResponse{URL: req.URL, Error: "Failed to fetch URL"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	// Parse HTML content
	title := extractTitle(string(body))
	description := extractMetaDescription(string(body))

	response := URLPreviewResponse{
		Title:       title,
		Description: description,
		URL:         req.URL,
	}

	jsonResponse, _ := json.Marshal(response)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonResponse)
}

func fetchURL(targetURL string) (int, []byte, error) {
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(targetURL)
	req.Header.SetMethod(fasthttp.MethodGet)
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Use Do instead of DoRedirects to prevent redirect-based SSRF
	// Each redirect would need to be validated
	err := httpClient.DoTimeout(req, resp, 10*time.Second)
	if err != nil {
		return 0, nil, err
	}

	// Handle redirects manually with validation
	redirectCount := 0
	maxRedirects := 5
	for resp.StatusCode() >= 300 && resp.StatusCode() < 400 && redirectCount < maxRedirects {
		location := string(resp.Header.Peek("Location"))
		if location == "" {
			break
		}

		// Resolve relative URLs
		baseURL, err := url.Parse(targetURL)
		if err != nil {
			return 0, nil, err
		}
		redirectURL, err := baseURL.Parse(location)
		if err != nil {
			return 0, nil, err
		}

		// Validate the redirect URL
		if err := validateURL(redirectURL.String()); err != nil {
			return 0, nil, errors.New("redirect to blocked URL: " + err.Error())
		}

		targetURL = redirectURL.String()
		req.SetRequestURI(targetURL)
		resp.Reset()

		err = httpClient.DoTimeout(req, resp, 10*time.Second)
		if err != nil {
			return 0, nil, err
		}
		redirectCount++
	}

	// Copy the body since we're releasing the response
	body := make([]byte, len(resp.Body()))
	copy(body, resp.Body())

	return resp.StatusCode(), body, nil
}

func extractTitle(html string) string {
	// Case-insensitive regex for title tag
	titleRegex := regexp.MustCompile(`(?i)<title[^>]*>([^<]*)</title>`)
	matches := titleRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

func extractMetaDescription(html string) string {
	// Case-insensitive regex for meta description
	// Handles both name="description" and property="og:description"
	patterns := []string{
		`(?i)<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>`,
		`(?i)<meta[^>]*content=["']([^"']*)["'][^>]*name=["']description["'][^>]*>`,
		`(?i)<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']*)["'][^>]*>`,
		`(?i)<meta[^>]*content=["']([^"']*)["'][^>]*property=["']og:description["'][^>]*>`,
	}

	for _, pattern := range patterns {
		regex := regexp.MustCompile(pattern)
		matches := regex.FindStringSubmatch(html)
		if len(matches) > 1 {
			return strings.TrimSpace(matches[1])
		}
	}
	return ""
}

func main() {
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			if string(ctx.Method()) == fasthttp.MethodPost {
				FetchURLPreview(ctx)
			} else {
				ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
			}
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
		}
	}

	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", requestHandler); err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}

