// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

const (
	maxResponseBodySize = 1024 * 1024 // 1MB limit
	maxRedirectCount    = 5
)

// isPrivateIP checks if an IP address is private/internal
func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}

	// Check for loopback
	if ip.IsLoopback() {
		return true
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return true
	}

	// Check for link-local
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for private ranges
	if ip.IsPrivate() {
		return true
	}

	// Additional check for IPv4 mapped IPv6 addresses
	if ip4 := ip.To4(); ip4 != nil {
		// 169.254.0.0/16 (link-local)
		if ip4[0] == 169 && ip4[1] == 254 {
			return true
		}
		// 127.0.0.0/8
		if ip4[0] == 127 {
			return true
		}
	}

	return false
}

// isHostAllowed validates that the host doesn't resolve to a private IP
func isHostAllowed(host string) (bool, error) {
	// Remove port if present
	hostname := host
	if h, _, err := net.SplitHostPort(host); err == nil {
		hostname = h
	}

	// Check if it's a direct IP address
	if ip := net.ParseIP(hostname); ip != nil {
		return !isPrivateIP(ip), nil
	}

	// Resolve hostname
	ips, err := net.LookupIP(hostname)
	if err != nil {
		return false, err
	}

	for _, ip := range ips {
		if isPrivateIP(ip) {
			return false, nil
		}
	}

	return len(ips) > 0, nil
}

// validateURL checks if the URL is safe to fetch
func validateURL(targetURL string) (*url.URL, error) {
	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL format")
	}

	// Only allow http and https schemes
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return nil, fmt.Errorf("URL must use http or https scheme")
	}

	// Check host is not empty
	if parsedURL.Host == "" {
		return nil, fmt.Errorf("URL must have a host")
	}

	// Check if host resolves to allowed IP
	allowed, err := isHostAllowed(parsedURL.Host)
	if err != nil {
		return nil, fmt.Errorf("failed to resolve host: %v", err)
	}
	if !allowed {
		return nil, fmt.Errorf("access to internal resources is not allowed")
	}

	return parsedURL, nil
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	// Validate URL and check for SSRF
	parsedURL, err := validateURL(targetURL)
	if err != nil {
		ctx.Error(err.Error(), fasthttp.StatusBadRequest)
		return
	}

	// Use fasthttp.Client to fetch with timeout
	client := &fasthttp.Client{
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
		MaxResponseBodySize: maxResponseBodySize,
		NoDefaultUserAgentHeader: true,
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(parsedURL.String())
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	// Perform request without following redirects automatically to validate each redirect
	if err := client.DoTimeout(freq, res, 15*time.Second); err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}

	// Handle redirects manually with validation
	redirectCount := 0
	for res.StatusCode() >= 300 && res.StatusCode() < 400 && redirectCount < maxRedirectCount {
		location := string(res.Header.Peek("Location"))
		if location == "" {
			break
		}

		// Resolve relative URLs
		redirectURL, err := parsedURL.Parse(location)
		if err != nil {
			ctx.Error("Invalid redirect URL", fasthttp.StatusBadGateway)
			return
		}

		// Validate redirect URL for SSRF
		_, err = validateURL(redirectURL.String())
