type URLRequest struct {
	URL string `json:"url"`
}

type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	URL         string `json:"url"`
	Error       string `json:"error,omitempty"`
}

var client = &fasthttp.Client{
	Dial:         fasthttp.DialDualStack,
	ReadTimeout:  3 * time.Second,
	WriteTimeout: 3 * time.Second,
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		response := URLPreviewResponse{Error: "Method not allowed"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{Error: "Invalid JSON body"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{Error: "URL field is required"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	title, description, err := fetchAndParseURL(req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: err.Error(),
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	response := URLPreviewResponse{
		Title:       title,
		Description: description,
		URL:         req.URL,
	}

	jsonResponse, _ := json.Marshal(response)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonResponse)
}

func fetchAndParseURL(url string) (string, string, error) {
	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(url)
	req.Header.SetMethod(fasthttp.MethodGet)
	req.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Use DoRedirects with max 10 redirects and 3 second timeout
	err := client.DoRedirects(req, resp, 10)
	if err != nil {
		return "", "", err
	}

	body := resp.Body()
	htmlContent := string(body)

	title := extractTitle(htmlContent)
	description := extractMetaDescription(htmlContent)

	return title, description, nil
}

func extractTitle(html string) string {
	// Case-insensitive regex for title tag
	titleRegex := regexp.MustCompile(`(?i)<title[^>]*>(.*?)</title>`)
	matches := titleRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

func extractMetaDescription(html string) string {
	// Case-insensitive regex for meta description
	// Handles both name="description" and property="description"
	descRegex := regexp.MustCompile(`(?i)<meta[^>]*(?:name|property)\s*=\s*["']description["'][^>]*content\s*=\s*["']([^"']*)["'][^>]*>`)
	matches := descRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}

	// Try alternate order: content before name
	descRegex2 := regexp.MustCompile(`(?i)<meta[^>]*content\s*=\s*["']([^"']*)["'][^>]*(?:name|property)\s*=\s*["']description["'][^>]*>`)
	matches = descRegex2.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}

	return ""
}

func main() {
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			FetchURLPreview(ctx)
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetBodyString("Not Found")
		}
	}

	server := &fasthttp.Server{
		Handler:      requestHandler,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
	}

	if err := server.ListenAndServe(":8080"); err != nil {
		panic(err)
	}
}

