package main

import (
	"encoding/json"
	"log"
	"net"
	"net/url"
	"regexp"
	"strings"

	"github.com/valyala/fasthttp"
)

type URLRequest struct {
	URL string `json:"url"`
}

type URLPreviewResponse struct {
	URL         string `json:"url"`
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

var client = &fasthttp.Client{
	Dial: func(addr string) (net.Conn, error) {
		// Extract host from addr (format: host:port)
		host, _, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, err
		}

		// Resolve the hostname to IP addresses
		ips, err := net.LookupIP(host)
		if err != nil {
			return nil, err
		}

		// Check all resolved IPs
		for _, ip := range ips {
			if isPrivateIP(ip) {
				return nil, &net.AddrError{Err: "access to private IP address is forbidden", Addr: ip.String()}
			}
		}

		return fasthttp.DialDualStack(addr)
	},
}

func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}

	// Check for loopback
	if ip.IsLoopback() {
		return true
	}

	// Check for link-local
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return true
	}

	// Check for private networks
	if ip.IsPrivate() {
		return true
	}

	// Additional check for IPv4
	if ip4 := ip.To4(); ip4 != nil {
		// 169.254.0.0/16 (link-local)
		if ip4[0] == 169 && ip4[1] == 254 {
			return true
		}
		// 127.0.0.0/8 (loopback)
		if ip4[0] == 127 {
			return true
		}
		// 0.0.0.0/8
		if ip4[0] == 0 {
			return true
		}
	}

	return false
}

func isValidURL(rawURL string) (bool, string) {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return false, "Invalid URL format"
	}

	// Only allow http and https schemes
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return false, "Only HTTP and HTTPS protocols are allowed"
	}

	// Get the host
	host := parsedURL.Hostname()
	if host == "" {
		return false, "URL must have a valid host"
	}

	// Block localhost variations
	lowerHost := strings.ToLower(host)
	if lowerHost == "localhost" || lowerHost == "127.0.0.1" || lowerHost == "::1" || lowerHost == "0.0.0.0" {
		return false, "Access to localhost is forbidden"
	}

	// Check if it's an IP address
	ip := net.ParseIP(host)
	if ip != nil {
		if isPrivateIP(ip) {
			return false, "Access to private IP addresses is forbidden"
		}
	}

	return true, ""
}

func extractTitle(html string) string {
	titleRegex := regexp.MustCompile(`(?i)<title[^>]*>([^<]+)</title>`)
	matches := titleRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

func extractMetaDescription(html string) string {
	// Try to match meta description tag
	descRegex := regexp.MustCompile(`(?i)<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["'][^>]*>`)
	matches := descRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}

	// Try alternative format where content comes before name
	descRegex2 := regexp.MustCompile(`(?i)<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["'][^>]*>`)
	matches = descRegex2.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}

	return ""
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	// Parse request body
	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		response := URLPreviewResponse{
			Error: "Invalid JSON body: " + err.Error(),
		}
		responseBytes, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(responseBytes)
		return
	}

	if req.URL == "" {
		response := URLPreviewResponse{
			Error: "URL field is required",
		}
		responseBytes, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(responseBytes)
		return
	}

	// Validate URL to prevent SSRF
	valid, errMsg := isValidURL(req.URL)
	if !valid {
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: errMsg,
		}
		responseBytes, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(responseBytes)
		return
	}

	// Prepare request and response
	fetchReq := fasthttp.AcquireRequest()
	fetchResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(fetchReq)
	defer fasthttp.ReleaseResponse(fetchResp)

	fetchReq.SetRequestURI(req.URL)
	fetchReq.Header.SetMethod(fasthttp.MethodGet)
	fetchReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Fetch URL with redirects (max 10 redirects)
	err := client.DoRedirects(fetchReq, fetchResp, 10)
	if err != nil {
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: "Failed to fetch URL: " + err.Error(),
		}
		responseBytes, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBody(responseBytes)
		return
	}

	// Get response body
	body := string(fetchResp.Body())

	// Extract title and description
	title := extractTitle(body)
	description := extractMetaDescription(body)

	// Build response
	response := URLPreviewResponse{
		URL:         req.URL,
		Title:       title,
		Description: description,
	}

	responseBytes, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBodyString(`{"error":"Failed to marshal response"}`)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(responseBytes)
}

func main() {
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			if string(ctx.Method()) == fasthttp.MethodPost {
				FetchURLPreview(ctx)
			} else {
				ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
				ctx.SetBodyString(`{"error":"Method not allowed"}`)
			}
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetBodyString(`{"error":"Not found"}`)
		}
	}

	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", requestHandler); err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}

