	}

	// Check for private ranges
	if ip.IsPrivate() {
		return true
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return true
	}

	// Check for multicast
	if ip.IsMulticast() {
		return true
	}

	// Additional check for IPv4 mapped IPv6 addresses
	if ip4 := ip.To4(); ip4 != nil {
		// 0.0.0.0/8
		if ip4[0] == 0 {
			return true
		}
		// 169.254.0.0/16 (link-local)
		if ip4[0] == 169 && ip4[1] == 254 {
			return true
		}
		// 127.0.0.0/8 (loopback)
		if ip4[0] == 127 {
			return true
		}
		// 10.0.0.0/8
		if ip4[0] == 10 {
			return true
		}
		// 172.16.0.0/12
		if ip4[0] == 172 && ip4[1] >= 16 && ip4[1] <= 31 {
			return true
		}
		// 192.168.0.0/16
		if ip4[0] == 192 && ip4[1] == 168 {
			return true
		}
	}

	return false
}

// validateURL checks if the URL is safe to fetch (not internal/private)
func validateURL(rawURL string) error {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return fmt.Errorf("invalid URL format")
	}

	// Only allow http and https schemes
	scheme := strings.ToLower(parsedURL.Scheme)
	if scheme != "http" && scheme != "https" {
		return fmt.Errorf("only http and https schemes are allowed")
	}

	host := parsedURL.Hostname()
	if host == "" {
		return fmt.Errorf("URL must have a host")
	}

	// Block localhost variations
	lowerHost := strings.ToLower(host)
	if lowerHost == "localhost" || lowerHost == "localhost.localdomain" {
		return fmt.Errorf("localhost is not allowed")
	}

	// Block common internal hostnames
	if strings.HasSuffix(lowerHost, ".local") || strings.HasSuffix(lowerHost, ".internal") {
		return fmt.Errorf("internal hostnames are not allowed")
	}

	// Resolve hostname to IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("failed to resolve hostname")
	}

	// Check all resolved IPs
	for _, ip := range ips {
		if isPrivateIP(ip) {
			return fmt.Errorf("access to private/internal IP addresses is not allowed")
		}
	}

	return nil
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	// Parse request body
	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		response := URLPreviewResponse{
			Error: "Invalid JSON body: " + err.Error(),
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(jsonResponse)
		return
	}

	if req.URL == "" {
		response := URLPreviewResponse{
			Error: "URL field is required",
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(jsonResponse)
		return
	}

	// Validate URL to prevent SSRF
	if err := validateURL(req.URL); err != nil {
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: "URL validation failed: " + err.Error(),
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(jsonResponse)
		return
	}

	// Prepare request and response
	httpReq := fasthttp.AcquireRequest()
	httpResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(httpReq)
	defer fasthttp.ReleaseResponse(httpResp)

	httpReq.SetRequestURI(req.URL)
	httpReq.Header.SetMethod(fasthttp.MethodGet)
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Fetch URL with redirects (max 10 redirects)
	err := client.DoRedirects(httpReq, httpResp, 10)
	if err != nil {
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: "Failed to fetch URL: " + err.Error(),
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBody(jsonResponse)
		return
	}

	// Get response body
	body := string(httpResp.Body())

	// Extract title and description
	title := extractTitle(body)
	description := extractMetaDescription(body)

	response := URLPreviewResponse{
		URL:         req.URL,
		Title:       title,
		Description: description,
	}

	jsonResponse, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBody([]byte(`{"error":"Failed to marshal response"}`))
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonResponse)
}

func main() {
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			if string(ctx.Method()) == fasthttp.MethodPost {
				FetchURLPreview(ctx)
			} else {
				ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
				ctx.SetBody([]byte(`{"error":"Method not allowed"}`))
			}
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetBody([]byte(`{"error":"Not found"}`))
		}
	}

	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", requestHandler); err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}

