	}

	for _, ip := range ips {
		if isPrivateIP(ip) {
			return fmt.Errorf("hostname resolves to private IP address")
		}
	}

	return nil
}

// safeDialer creates a dialer that prevents connections to private IPs
func safeDialer(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	// Resolve and validate before connecting
	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, err
	}

	for _, ip := range ips {
		if isPrivateIP(ip) {
			return nil, fmt.Errorf("connection to private IP addresses is not allowed")
		}
	}

	// Connect with timeout
	dialer := &net.Dialer{
		Timeout: 5 * time.Second,
	}

	// Try to connect to resolved IPs
	for _, ip := range ips {
		if isPrivateIP(ip) {
			continue
		}
		conn, err := dialer.Dial("tcp", net.JoinHostPort(ip.String(), port))
		if err == nil {
			return conn, nil
		}
	}

	return nil, fmt.Errorf("failed to connect to any resolved IP")
}

