package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net"
	"net/url"
	"regexp"
	"strings"
	"time"

	"github.com/valyala/fasthttp"
)

type URLRequest struct {
	URL string `json:"url"`
}

type URLPreviewResponse struct {
	URL         string `json:"url"`
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

var client = &fasthttp.Client{
	ReadTimeout:  5 * time.Second,
	WriteTimeout: 5 * time.Second,
	Dial: func(addr string) (net.Conn, error) {
		host, _, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, fmt.Errorf("invalid address: %v", err)
		}

		// Resolve the hostname to IP addresses
		ips, err := net.LookupIP(host)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve host: %v", err)
		}

		// Check all resolved IPs
		for _, ip := range ips {
			if isPrivateIP(ip) {
				return nil, fmt.Errorf("access to private IP addresses is not allowed")
			}
		}

		// Connect to the address
		return fasthttp.DialTimeout(addr, 5*time.Second)
	},
}

func isPrivateIP(ip net.IP) bool {
	if ip == nil {
		return true
	}

	// Check for loopback
	if ip.IsLoopback() {
		return true
	}

	// Check for unspecified (0.0.0.0 or ::)
	if ip.IsUnspecified() {
		return true
	}

	// Check for link-local
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for private networks
	if ip.IsPrivate() {
		return true
	}

	// Additional checks for IPv4
	if ip4 := ip.To4(); ip4 != nil {
		// 169.254.0.0/16 - Link-local
		if ip4[0] == 169 && ip4[1] == 254 {
			return true
		}
		// 127.0.0.0/8 - Loopback
		if ip4[0] == 127 {
			return true
		}
		// 0.0.0.0/8 - Current network
		if ip4[0] == 0 {
			return true
		}
	}

	return false
}

func isValidURL(rawURL string) error {
	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		return fmt.Errorf("invalid URL format")
	}

	// Only allow http and https schemes
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return fmt.Errorf("only http and https schemes are allowed")
	}

	// Check if host is empty
	if parsedURL.Hostname() == "" {
		return fmt.Errorf("hostname is required")
	}

	host := parsedURL.Hostname()

	// Check if it's an IP address
	if ip := net.ParseIP(host); ip != nil {
		if isPrivateIP(ip) {
			return fmt.Errorf("access to private IP addresses is not allowed")
		}
		return nil
	}

	// Check for localhost variations
	lowerHost := strings.ToLower(host)
	if lowerHost == "localhost" || strings.HasSuffix(lowerHost, ".localhost") {
		return fmt.Errorf("access to localhost is not allowed")
	}

	// Resolve hostname and check IPs
	ips, err := net.LookupIP(host)
	if err != nil {
		return fmt.Errorf("failed to resolve hostname")
	}

	for _, ip := range ips {
		if isPrivateIP(ip) {
			return fmt.Errorf("access to private IP addresses is not allowed")
		}
	}

	return nil
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	// Parse request body
	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{Error: "Invalid JSON body"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{Error: "URL field is required"}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	// Validate URL for SSRF protection
	if err := isValidURL(req.URL); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: err.Error(),
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	// Fetch the URL content
	httpReq := fasthttp.AcquireRequest()
	httpResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(httpReq)
	defer fasthttp.ReleaseResponse(httpResp)

	httpReq.SetRequestURI(req.URL)
	httpReq.Header.SetMethod(fasthttp.MethodGet)
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Use DoRedirects to follow redirects (max 10 redirects)
	if err := client.DoRedirects(httpReq, httpResp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		response := URLPreviewResponse{
			URL:   req.URL,
			Error: "Failed to fetch URL: " + err.Error(),
		}
		jsonResponse, _ := json.Marshal(response)
		ctx.SetBody(jsonResponse)
		return
	}

	// Parse HTML content
	body := string(httpResp.Body())
	title := extractTitle(body)
	description := extractMetaDescription(body)

	response := URLPreviewResponse{
		URL:         req.URL,
		Title:       title,
		Description: description,
	}

	jsonResponse, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		errorResponse := URLPreviewResponse{Error: "Failed to marshal response"}
		jsonResponse, _ = json.Marshal(errorResponse)
		ctx.SetBody(jsonResponse)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonResponse)
}

func extractTitle(html string) string {
	// Case-insensitive regex for title tag
	titleRegex := regexp.MustCompile(`(?i)<title[^>]*>([^<]*)</title>`)
	matches := titleRegex.FindStringSubmatch(html)
	if len(matches) > 1 {
		return strings.TrimSpace(matches[1])
	}
	return ""
}

func extractMetaDescription(html string) string {
	// Case-insensitive regex for meta description
	// Handles both name="description" and property="og:description"
	patterns := []string{
		`(?i)<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>`,
		`(?i)<meta[^>]*content=["']([^"']*)["'][^>]*name=["']description["'][^>]*>`,
		`(?i)<meta[^>]*property=["']og:description["'][^>]*content=["']([^"']*)["'][^>]*>`,
		`(?i)<meta[^>]*content=["']([^"']*)["'][^>]*property=["']og:description["'][^>]*>`,
	}

	for _, pattern := range patterns {
		regex := regexp.MustCompile(pattern)
		matches := regex.FindStringSubmatch(html)
		if len(matches) > 1 {
			return strings.TrimSpace(matches[1])
		}
	}
	return ""
}

func main() {
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			if string(ctx.Method()) == fasthttp.MethodPost {
				FetchURLPreview(ctx)
			} else {
				ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
			}
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
		}
	}

	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", requestHandler); err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}

